async function generatePrompt(request) {
    try {
        const response = await fetch('/api/ai/generate', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(request)
        });
        if (!response.ok) {
            const error = await response.json();
            throw new Error(error.error || '生成失败');
        }
        const data = await response.json();
        return {
            title: data.title,
            prompt: data.prompt,
            promptCn: data.promptCn,
            negativePrompt: data.negativePrompt,
            negativePromptCn: data.negativePromptCn,
            description: data.description,
            success: true
        };
    } catch (error) {
        console.error('生成提示词失败:', error);
        return {
            title: '',
            prompt: '',
            success: false,
            error: error instanceof Error ? error.message : '未知错误'
        };
    }
}
async function optimizePrompt(request) {
    try {
        const response = await fetch('/api/ai/optimize', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(request)
        });
        if (!response.ok) {
            const error = await response.json();
            throw new Error(error.error || '优化失败');
        }
        const data = await response.json();
        return {
            optimizedPrompt: data.optimizedPrompt,
            optimizedPromptCn: data.optimizedPromptCn,
            suggestions: data.suggestions || [],
            success: true
        };
    } catch (error) {
        console.error('优化提示词失败:', error);
        return {
            optimizedPrompt: '',
            suggestions: [],
            success: false,
            error: error instanceof Error ? error.message : '未知错误'
        };
    }
}
function isAIConfigured() {
    // 服务端API路由会检查配置，客户端始终返回true
    return true;
}
async function analyzeImage(imageBase64) {
    try {
        const response = await fetch('/api/ai/analyze', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                imageBase64
            })
        });
        if (!response.ok) {
            const error = await response.json();
            throw new Error(error.error || '分析失败');
        }
        const data = await response.json();
        return {
            analysis: data,
            success: true
        };
    } catch (error) {
        console.error('识图分析失败:', error);
        return {
            analysis: {},
            success: false,
            error: error instanceof Error ? error.message : '未知错误'
        };
    }
}
